    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reject both thresholds. Use de minimis AUD 5,000 and basket AUD 50,000."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Keep 24 months after Completion as the base."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Enforce a 100% cap and six-year minimum, independent of the capped general regime."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Amend so the fraud carve-out is unqualified and applies to every applicable provision."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Prohibit reliance on prudent search or equivalent deemed disclosure for representing warranties. Any disclosure must remain true to what was actually inspected."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete Clause 8.3 entirely or replace with a qualified version that names at least two Seller knowledge persons"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require effective written Bluefen consent *and* contemporaneous evidence that the change-control conditions in DD-002 clause 11.3 are satisfied, delivered *before* Completion."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "For any post-Completion exercise, require the same IRO + Amelia Frost approval gate."
    },
